1277	/// Time one sample (`inner` back-to-back calls), divide down to a
1278	/// per-call value in **picoseconds**, and record it, clamping at
1279	/// the histogram bounds — a suspend-inflated or wedged sample
1280	/// must not panic a long run ([`crate::report::warn_invalid`] flags it instead).
1281	///
1282	/// - The seam dither (a random sub-quantum spin before the timer
1283	///   pair, outside the timed interval) stops the run's aggregate
1284	///   means from carrying a coherent ±quantum phase bias — up to
1285	///   ~±2% on fast benches (see
1286	///   notes/design.md#dithering-random-phase-injection).
1287	fn record_sample<B: Bench>(
1288	    bench: &mut B,
1289	    inner: u64,
1290	    pipeline: &mut BatchPipeline,
1291	    dither: &mut Dither,
1292	) -> u64 {
1293	    dither.spin();
1294	    let start = std::time::Instant::now();
1295	    for _ in 0..inner {
1296	        black_box(bench.step());
1297	    }
1298	    let elapsed_ps = start.elapsed().as_nanos().saturating_mul(1000);
1299	    let per_call_ps = round_elapsed_ps(elapsed_ps, inner);
1300	    pipeline.push(per_call_ps);
1301	    per_call_ps
1302	}
1303	
1304	/// Per-call value: `elapsed_ps / inner`, rounded to nearest, in
1305	/// u128 so an hours-long suspend-inflated sample can't overflow
1306	/// the ×1000 ns→ps conversion; the cast clamps at u64::MAX and
1307	/// `saturating_record` clamps again at the histogram bound.
1308	fn round_elapsed_ps(elapsed_ps: u128, inner: u64) -> u64 {
1309	    let inner = inner as u128;
1310	    ((elapsed_ps + inner / 2) / inner).min(u64::MAX as u128) as u64
1311	}
