1313	/// Paired run-start readings of `CLOCK_MONOTONIC` and
1314	/// `CLOCK_BOOTTIME`, for detecting a system suspend that spanned
1315	/// a measurement run.
1316	///
1317	/// - `CLOCK_MONOTONIC` freezes while the system is suspended;
1318	///   `CLOCK_BOOTTIME` keeps counting — the divergence of the two
1319	///   elapsed times is the time spent suspended.
1320	/// - Uses std `Instant` (`CLOCK_MONOTONIC`), not `minstant`: we
1321	///   think the TSC keeps counting across s2idle suspend, which is
1322	///   exactly the clock behavior being detected.
1323	struct ClockPair {
1324	    mono: std::time::Instant,
1325	    boot_ns: u64,
1326	}
1327	
1328	impl ClockPair {
1329	    /// Capture both clocks now.
1330	    fn now() -> Self {
1331	        Self {
1332	            mono: std::time::Instant::now(),
1333	            boot_ns: boottime_ns(),
1334	        }
1335	    }
1336	
1337	    /// Seconds the system spent suspended since [`now`][Self::now]:
1338	    /// boottime elapsed minus monotonic elapsed (~0 when no
1339	    /// suspend occurred).
1340	    fn suspended_s(&self) -> f64 {
1341	        let boot_s = (boottime_ns() - self.boot_ns) as f64 / 1e9;
1342	        let mono_s = self.mono.elapsed().as_nanos() as f64 / 1e9;
1343	        boot_s - mono_s
1344	    }
1345	}
1346	
1347	/// Current `CLOCK_BOOTTIME` reading in nanoseconds.
1348	fn boottime_ns() -> u64 {
1349	    let mut ts = libc::timespec {
1350	        tv_sec: 0,
1351	        tv_nsec: 0,
1352	    };
1353	    // SAFETY: clock_gettime only writes `ts`; CLOCK_BOOTTIME is
1354	    // always valid on Linux.
1355	    let rc = unsafe { libc::clock_gettime(libc::CLOCK_BOOTTIME, &mut ts) };
1356	    assert_eq!(rc, 0, "clock_gettime(CLOCK_BOOTTIME) failed");
1357	    ts.tv_sec as u64 * 1_000_000_000 + ts.tv_nsec as u64
1358	}
