1	//! The bench report: everything that turns a finished [`crate::harness::RunOutput`] into text.
2	//!
3	//! Split out of `harness.rs` so measuring and rendering stop sharing a file. The seam is
4	//! `RunOutput` itself, which the harness produces and this module consumes; nothing here feeds
5	//! back into a measurement.
6	//!
7	//! - **The band table and its summary rows** ([`print_report`]): per-quantile-band
8	//!   first/last/range/count/mean, then whole-histogram mean/stdev, the trimmed pair, the clock's
9	//!   `quantum`, and the block-replication rows.
10	//! - **The grade block**: the `env` rows grading the box across warmup and bench, over the `run`
11	//!   row grading the numbers themselves.
12	//! - **Formatting primitives** ([`fmt_commas`], [`fmt_commas_f64`], [`display_cols`],
13	//!   [`decimal_align`]) that `probe.rs` and `band_table.rs` share.
14	//!
15	//! Column alignment here assumes a terminal's uniform character cell. That assumption lives in
16	//! [`display_cols`] and nowhere else, so a renderer that measures text instead (a GUI) replaces
17	//! this module rather than editing it.
18	
19	use hdrhistogram::Histogram;
20	
21	use crate::bands::{self, BandLabels};
22	use crate::harness::{
23	    HIST_HIGH_PS, PS_PER_NS, ProbeSummary, RunCfg, RunOutput, WarmClock, WarmExit,
24	};
25	use crate::ticks;
26	
27	/// Grade-block column widths, sized to each column's widest
28	/// realistic cell so right-aligned cells always leave the
29	/// two-space gap `qualify-environment`'s parser splits on.
30	///
31	/// - label columns (`grade`, `phase`) are left-aligned
32	/// - value columns are right-aligned; a signal that does not
33	///   apply to a row prints [`GB_BLANK`]
34	const GB_GRADE_W: usize = 5;
35	/// `phase` column: `warmup` is the widest phase.
36	const GB_PHASE_W: usize = 6;
37	/// `settle` column: a state-carrying cell like `12.34s @4.35GHz` is the widest.
38	const GB_SETTLE_W: usize = 15;
39	/// `worst` column: the composite letter under its header.
40	const GB_WORST_W: usize = 5;
41	/// Percentage signal cells (`spread`, `drift`): `100.00% A`.
42	const GB_PCT_W: usize = 9;
43	/// `bursts` cells: `100% B`.
44	const GB_BURSTS_W: usize = 6;
45	/// `interference` column: its own header is the widest cell.
46	const GB_INT_W: usize = 12;
47	/// `step` cells carry the timestamp: `100.00% @99.99s F`.
48	const GB_STEP_W: usize = 17;
49	/// Blank grade-block cell: this signal does not apply to this
50	/// row. A plain typeable hyphen, not an em dash.
51	const GB_BLANK: &str = "-";
52	
53	/// `CLOCK_BOOTTIME` minus `CLOCK_MONOTONIC` elapsed divergence
54	/// (seconds) at or above which [`warn_invalid`] reports that the
55	/// system suspended during the run.
56	const SUSPEND_WARN_S: f64 = 1.0;
57	
58	/// The clock's per-sample resolution: one tick spread across the `inner` calls it brackets.
59	///
60	/// A sample times `inner` calls in one bracket, so the smallest per-call step the clock can
61	/// express is a tick divided by `inner`. It is the number that says whether a printed spread
62	/// describes the workload or the clock's lattice: a core spread well below `q` is the lattice
63	/// (rpi5-20cd's 54 MHz timer puts `q` at ~2% of the value), well above it is the workload.
64	///
65	/// - Sizing does not chase it. `pick_inner` targets framing domination, which fixes the
66	///   *relative* quantum at `tick / (RATIO * frame)`, a property of the box rather than the
67	///   bench. Chasing it instead would smear the tail linearly for precision the dither and a
68	///   few million samples already provide.
69	/// - Degenerate inputs yield 0 rather than an infinity in a report column; neither is reachable
70	///   (`pick_inner` clamps `inner` to at least 1).
71	fn quantum_ns(ticks_per_ns: f64, inner: u64) -> f64 {
72	    if ticks_per_ns <= 0.0 || inner == 0 {
73	        return 0.0;
74	    }
75	    1.0 / ticks_per_ns / inner as f64
76	}
77	
78	/// Split an environment probe series into the two stretches the environment grade scores: the
79	/// warmup's trailing window and the probes taken while the bench ran.
80	///
81	/// - `warmup` is how many leading probes came from warmup (see [`RunOutput::warmup_probes`]);
82	///   it is clamped to the series length, so a truncated series can't panic.
83	/// - The warmup side's graded tail is the last `tail_len` probes: the warm exit window the
84	///   stopping rule graded ([`RunOutput::warm_tail`]), so the letter printed is the letter the
85	///   exit saw, one computation rather than two windows that can disagree. Absorbing a ramp is
86	///   warmup's job, so the stretch before the window is deliberately ungraded.
87	/// - Grading the two separately also stops the boundary between them from reading as a step,
88	///   which a blended series invents whenever warmup starts colder than the run.
89	///
90	/// Returns `(warm, tail, during)`: the whole warmup stretch (the one
91	/// `RunOutput::warm_settle` was scored over), its tail window (what the warmup grade reads),
92	/// and the bench stretch.
93	pub(crate) fn env_stretches(
94	    probes: &[ProbeSummary],
95	    warmup: usize,
96	    tail_len: usize,
97	) -> (&[ProbeSummary], &[ProbeSummary], &[ProbeSummary]) {
98	    let (warm, during) = probes.split_at(warmup.min(probes.len()));
99	    let tail = &warm[warm.len() - tail_len.min(warm.len())..];
100	    (warm, tail, during)
101	}
102	
103	/// Print `WARNING` lines when the finished run's tail-sensitive
104	/// stats — `max` and the untrimmed mean/stdev — are poisoned:
105	///
106	/// - the system suspended during the run (clock divergence — a
107	///   mid-sample suspend inflates that sample by the sleep gap,
108	///   even under the histogram bound);
109	/// - one or more samples clamped at [`HIST_HIGH_PS`] (a wedged or
110	///   suspend-inflated sample with no detected suspend).
111	///
112	/// A few inflated samples out of millions land in the extreme
113	/// tail band: percentile boundaries and the trimmed non-tail
114	/// stats are unaffected, so the flag names what died rather than
115	/// condemning the whole report. Called at the end of
116	/// [`print_report`] so the flag is the last thing in the bench's
117	/// report, where it can't scroll out of mind. Prints one
118	/// `WARNING {name}:` header with each finding indented below it,
119	/// keeping the findings visible next to the long bench name.
120	///
121	/// Warnings are for stats that are *invalid* — poisoned by a
122	/// suspend or a clamp. The run gauge never routes here: its
123	/// signals describe the run truthfully, and much of what they
124	/// describe belongs to the workload rather than the machine.
125	pub(crate) fn warn_invalid(name: &str, hist: &Histogram<u64>, suspended_s: f64) {
126	    let mut findings: Vec<String> = Vec::new();
127	    if suspended_s >= SUSPEND_WARN_S {
128	        findings.push(format!(
129	            "system suspended ~{suspended_s:.1}s during the run; max/mean/stdev poisoned"
130	        ));
131	    }
132	    if !hist.is_empty() && hist.max() >= HIST_HIGH_PS {
133	        findings.push(format!(
134	            "sample(s) clamped at the {}s histogram bound; max/mean/stdev poisoned",
135	            HIST_HIGH_PS / 1_000_000_000_000
136	        ));
137	    }
138	    if !findings.is_empty() {
139	        println!("WARNING {name}:");
140	        for finding in &findings {
141	            println!("  {finding}");
142	        }
143	    }
144	}
