146	/// Format an integer with thousands separators, e.g.
147	/// `12345` → `"12,345"`.
148	pub fn fmt_commas(n: u64) -> String {
149	    let s = n.to_string();
150	    let mut result = String::new();
151	    for (i, c) in s.chars().rev().enumerate() {
152	        if i > 0 && i % 3 == 0 {
153	            result.push(',');
154	        }
155	        result.push(c);
156	    }
157	    result.chars().rev().collect()
158	}
