160	/// Format a step signal's ` @<time>s` suffix, empty when the
161	/// signal did not fire.
162	///
163	/// One place, used by both the environment and run grades: the two
164	/// call sites previously carried their own format strings and had
165	/// drifted to 3 and 1 decimals, printing the same quantity at
166	/// different precision on adjacent lines.
167	///
168	/// - Two decimals (10 ms) because both series locate a step to
169	///   within one batch or seam, and [`crate::harness::BATCH_TARGET_SECONDS`] plus
170	///   [`crate::harness::BATCH_SAMPLES`] put that at ~15-50 ms. Finer would claim
171	///   resolution neither series has; coarser would lose the grid.
172	fn step_at_suffix(step_frac: f64, step_at_s: f64) -> String {
173	    if step_frac > 0.0 {
174	        format!(" @{step_at_s:.2}s")
175	    } else {
176	        String::new()
177	    }
178	}
