180	/// One percentage signal cell of the grade block: `value letter`
181	/// at the block's own fixed two-decimal precision (`--decimals`
182	/// governs the report's time columns, never these ratios).
183	fn pct_cell(frac: f64, letter: char) -> String {
184	    format!("{:.2}% {letter}", frac * 100.0)
185	}
186	
187	/// A `bursts` cell: whole percent, since the signal counts
188	/// batches and finer digits would be false precision.
189	fn burst_cell(frac: f64, letter: char) -> String {
190	    format!("{:.0}% {letter}", frac * 100.0)
191	}
192	
193	/// A `step` cell: the one signal carrying a timestamp, at the
194	/// 10 ms precision batches can actually locate a shift to.
195	fn step_cell(step_frac: f64, step_at_s: f64, letter: char) -> String {
196	    format!(
197	        "{:.2}%{} {letter}",
198	        step_frac * 100.0,
199	        step_at_suffix(step_frac, step_at_s)
200	    )
201	}
