225	/// Format a float with `decimals` fractional digits and thousands
226	/// separators on the integer part.
227	/// Width of a rendered cell in terminal columns.
228	///
229	/// Three quantities coincide for the ASCII this report prints and diverge otherwise:
230	/// `str::len()` counts *bytes*, `{:>n$}` padding counts *chars*, and a terminal renders
231	/// *columns* (CJK is two, combining marks are zero). Counting chars is what agrees with the
232	/// padder, so a column stays square; the point of routing every measurement through one function
233	/// is that swapping in a width-aware crate later means changing this body and nothing else.
234	pub fn display_cols(s: &str) -> usize {
235	    s.chars().count()
236	}
237	
238	/// Split a rendered number at its decimal point: `"15,974.399"` gives `("15,974", "399")`, and a
239	/// number without one gives an empty fraction.
240	fn split_decimal(s: &str) -> (&str, &str) {
241	    match s.find('.') {
242	        Some(i) => (&s[..i], &s[i + 1..]),
243	        None => (s, ""),
244	    }
245	}
246	
247	/// Pad a rendered number so a column of them lines up on the decimal point.
248	///
249	/// Right-justifying on the last character aligns the trailing unit but not the point, which
250	/// staggers as soon as one row carries more decimals than its neighbours: `quantum` prints at
251	/// least three (see [`quantum_ns`]) while every other row follows `--decimals`. Padding the
252	/// integer side to `int_cols` and the fraction to `frac_cols` puts every point in one column and
253	/// every following ` ns` in another.
254	///
255	/// - A value with no fraction in a column that has one is only reachable at `--decimals 0`,
256	///   where `quantum` still prints three. It pads across the point's column as well, so no row
257	///   renders a dangling `.`.
258	fn decimal_align(s: &str, int_cols: usize, frac_cols: usize) -> String {
259	    let (int, frac) = split_decimal(s);
260	    if frac_cols == 0 {
261	        return format!("{int:>int_cols$}");
262	    }
263	    if s.contains('.') {
264	        format!("{int:>int_cols$}.{frac:<frac_cols$}")
265	    } else {
266	        let blank = frac_cols + 1;
267	        format!("{int:>int_cols$}{:<blank$}", "")
268	    }
269	}
270	
271	pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
272	    let s = format!("{n:.decimals$}");
273	    let (sign, body) = match s.strip_prefix('-') {
274	        Some(rest) => ("-", rest),
275	        None => ("", s.as_str()),
276	    };
277	    let (int_part, frac_part) = match body.find('.') {
278	        Some(i) => (&body[..i], &body[i..]),
279	        None => (body, ""),
280	    };
281	    let int_num: u64 = int_part.parse().unwrap_or(0);
282	    format!("{sign}{}{frac_part}", fmt_commas(int_num))
283	}
284	
285	/// Index of the band containing `mid_rank`, over the full boundary
286	/// ladder `bounds` (`n_bands = bounds.len() - 1`).
287	///
288	/// - Bands are **right-closed** `(lower, upper]`: a rank exactly on a
289	///   boundary falls in the band that boundary *caps* — a single
290	///   sample's mid-rank of 0.5 lands in `p50`, not `p60`. This matches
291	///   the upper-boundary row labels and the CDF reading of a
292	///   percentile (value at or below which that fraction of samples
293	///   falls). See [`print_report`] for the convention and references.
294	/// - `mid_rank` is the Hazen plotting position `(i - 0.5) / n` of the
295	///   sample's rank, computed by the caller.
296	fn band_index(mid_rank: f64, bounds: &[bands::Boundary]) -> usize {
297	    let n_bands = bounds.len() - 1;
298	    bounds[1..]
299	        .iter()
300	        .position(|b| mid_rank <= b.pct)
301	        .unwrap_or(n_bands - 1)
302	}
303	
304	/// Build the trimmed-stat range label from the populated bands
305	/// below the n2 ≡ p99 tail cut.
306	///
307	/// - Names the first..last populated band in `band_count[..trim_bands]`
308	///   by its **upper** boundary (`bounds[i + 1]`), matching the row
309	///   labels — so the label tracks the real extent of the trimmed
310	///   data rather than asserting a `min` row (never printed — rows use
311	///   upper boundaries) or an `n2` band that can be empty.
312	/// - Collapses to a single name when one band holds all the trimmed
313	///   data (`p60`, not `p60..p60`).
314	/// - Empty string when no trimmed band is populated — only with no
315	///   samples at all, where the caller's `trim` is `None` and the
316	///   label goes unused.
317	fn trim_range_label(
318	    bounds: &[bands::Boundary],
319	    band_count: &[u64],
320	    trim_bands: usize,
321	    style: BandLabels,
322	) -> String {
323	    let first = (0..trim_bands).find(|&i| band_count[i] > 0);
324	    let last = (0..trim_bands).rev().find(|&i| band_count[i] > 0);
325	    match (first, last) {
326	        (Some(f), Some(l)) if f == l => bounds[f + 1].trim_name(style).to_string(),
327	        (Some(f), Some(l)) => format!(
328	            "{}..{}",
329	            bounds[f + 1].trim_name(style),
330	            bounds[l + 1].trim_name(style),
331	        ),
332	        _ => String::new(),
333	    }
334	}
335	
336	/// Print the full bench report: header line (logfmt-style metadata),
337	/// per-band histogram, whole-histogram mean/stdev, and trimmed
338	/// mean/stdev (every band below the n2 ≡ p99 tail cut). The trimmed
339	/// rows are labeled by the span of populated non-tail bands (e.g.
340	/// `mean z4..n2`), so `min` — never a row — is not asserted and an
341	/// empty n2 band is not named; see the label derivation below.
342	///
343	/// Each histogram row is one band, labeled by its **upper**
344	/// boundary — deciles in the body (`p10` … `p90`), nines/zeros in
345	/// the tails (`zK`/`nK` = fraction 10^-K of samples below/above
346	/// the boundary) — the lower boundary being the previous printed
347	/// row (empty bands are skipped). Bands are **right-closed**
348	/// `(lower, upper]` (see [`band_index`]): a sample whose rank lands
349	/// exactly on a boundary counts in the band that boundary caps, so a
350	/// lone median sample reads `p50`, not `p60` — matching the
351	/// upper-boundary label and the CDF definition of a percentile. This
352	/// is `pandas.cut`'s `right=True` convention; the rank is the Hazen
353	/// plotting position `(i - 0.5) / n`. Label style comes from
354	/// `cfg.band_labels` and is recorded as `labels=` in the header
355	/// metadata so saved outputs are self-describing. Values are raw:
356	/// nothing is subtracted, so a column is what the apparatus
357	/// measured. The untrimmed `stdev` is the
358	/// hdrhistogram-native stdev, which includes the ms-scale outliers
359	/// in the tail band. Ends with `WARNING` lines flagging poisoned
360	/// stats when they apply — `suspended_s` comes from
361	/// [`crate::harness::run_adaptive`] (see [`warn_invalid`]).
362	pub fn print_report(name: &str, out: &RunOutput, cfg: &RunCfg) {
363	    let hist = &out.hist;
364	    let outer = out.outer;
365	    let inner = out.inner;
366	    let duration_s = out.duration_s;
367	    let suspended_s = out.suspended_s;
368	    let block_stats = out.block_stats.as_ref();
369	    // Header line: bench name + logfmt-style metadata.
370	    let total = outer * inner;
371	    let blocks_meta = match block_stats {
372	        Some(b) => format!(" blocks={}", b.blocks),
373	        None => String::new(),
374	    };
375	    let batches_meta = format!(" batches={}", out.batches.len());
376	    // The warm cell is this run's total spend over its total
377	    // allowance: settle budget (when this run ran the process
378	    // warm) plus the cap.
379	    println!(
380	        "{name} [duration={:.1}s warm={:.2}/{:.1}s outer={} inner={} calls={}{blocks_meta}{batches_meta} labels={}]:",
381	        duration_s,
382	        out.warm_used_s,
383	        out.warm_budget_s,
384	        fmt_commas(outer),
385	        inner,
386	        fmt_commas(total),
387	        cfg.band_labels.as_str(),
388	    );
389	
390	    let bounds = bands::boundaries();
391	
392	    // Trim anchor: bands at or above the n2 (p99) boundary are
393	    // the "tail" — excluded from the trimmed stats no matter how
394	    // many finer tail bands subdivide them.
395	    #[allow(clippy::unwrap_used)]
396	    // OK: boundaries() always emits n2 (N_DEPTH >= 2)
397	    let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();
398	
399	    let n_bands = bounds.len() - 1;
400	    let sample_count = hist.len();
401	
402	    // Accumulate per-band stats by walking recorded histogram buckets.
403	    // Each bucket is assigned to the band containing its midpoint rank.
404	    let mut band_first = vec![u64::MAX; n_bands];
405	    let mut band_last = vec![0u64; n_bands];
406	    let mut band_count = vec![0u64; n_bands];
407	    let mut band_sum = vec![0u128; n_bands];
408	
409	    let mut cumulative = 0u64;
410	    for iv in hist.iter_recorded() {
411	        let value = iv.value_iterated_to();
412	        let count = iv.count_at_value();
413	        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
414	        let idx = band_index(mid_rank, &bounds);
415	        band_first[idx] = band_first[idx].min(value);
416	        band_last[idx] = band_last[idx].max(value);
417	        band_count[idx] += count;
418	        band_sum[idx] += value as u128 * count as u128;
419	        cumulative += count;
420	    }
421	
422	    // Trimmed-stat range label, derived from the populated bands.
423	    let trim_range = trim_range_label(&bounds, &band_count, trim_bands, cfg.band_labels);
424	    let mean_trim_label = format!("mean {trim_range}");
425	    let stdev_trim_label = format!("stdev {trim_range}");
426	
427	    // Build rendered rows: (label, first, last, range, count, mean).
428	    struct BandRow {
429	        label: String,
430	        first: String,
431	        last: String,
432	        range: String,
433	        count: String,
434	        mean: String,
435	    }
436	
437	    let mut rows: Vec<BandRow> = Vec::new();
438	    for i in 0..n_bands {
439	        if band_count[i] == 0 {
440	            continue;
441	        }
442	        let mean_ns = band_sum[i] as f64 / band_count[i] as f64 / PS_PER_NS;
443	        rows.push(BandRow {
444	            label: bounds[i + 1].label(cfg.band_labels),
445	            first: fmt_commas_f64(band_first[i] as f64 / PS_PER_NS, cfg.decimals),
446	            last: fmt_commas_f64(band_last[i] as f64 / PS_PER_NS, cfg.decimals),
447	            range: fmt_commas_f64(
448	                (band_last[i] - band_first[i] + 1) as f64 / PS_PER_NS,
449	                cfg.decimals,
450	            ),
451	            count: fmt_commas(band_count[i]),
452	            mean: fmt_commas_f64(mean_ns, cfg.decimals),
453	        });
454	    }
455	
456	    // Whole-histogram and trimmed (every band below the n2 ≡ p99
457	    // tail cut) summary values, rendered before the width
458	    // pass so the widths account for them — the untrimmed stdev
459	    // is often wider than any band mean and would otherwise
460	    // overflow its column, shifting its line right.
461	    let hist_mean = hist.mean() / PS_PER_NS;
462	    let hist_mean_str = fmt_commas_f64(hist_mean, cfg.decimals);
463	    let hist_stdev_str = fmt_commas_f64(hist.stdev() / PS_PER_NS, cfg.decimals);
464	
465	    let trim_count: u64 = band_count[..trim_bands].iter().sum();
466	    let trim = if trim_count > 0 {
467	        let trim_sum: u128 = band_sum[..trim_bands].iter().sum();
468	        let trim_mean = trim_sum as f64 / trim_count as f64 / PS_PER_NS;
469	
470	        // Variance: walk histogram buckets, include only non-tail bands.
471	        let mut trim_var_sum = 0.0f64;
472	        let mut trim_var_count = 0u64;
473	        let mut cum = 0u64;
474	        for iv in hist.iter_recorded() {
475	            let value = iv.value_iterated_to();
476	            let count = iv.count_at_value();
477	            let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
478	            let idx = band_index(mid_rank, &bounds);
479	            if idx < trim_bands {
480	                let diff = value as f64 / PS_PER_NS - trim_mean;
481	                trim_var_sum += diff * diff * count as f64;
482	                trim_var_count += count;
483	            }
484	            cum += count;
485	        }
486	        let trim_stdev = if trim_var_count > 1 {
487	            (trim_var_sum / trim_var_count as f64).sqrt()
488	        } else {
489	            0.0
490	        };
491	
492	        Some((
493	            fmt_commas_f64(trim_mean, cfg.decimals),
494	            fmt_commas_f64(trim_stdev, cfg.decimals),
495	        ))
496	    } else {
497	        None
498	    };
499	
500	    // Block-replication summary strings, rendered before the
501	    // width pass like the other summary lines.
502	    let block_strs = block_stats.map(|b| {
503	        (
504	            fmt_commas_f64(b.mean_ns, cfg.decimals),
505	            fmt_commas_f64(b.ci95_ns, cfg.decimals),
506	            fmt_commas_f64(b.lsc_ns, cfg.decimals),
507	        )
508	    });
509	
510	    // The clock's per-sample quantum, rendered next to the spread
511	    // rows because that is where it is needed: it says whether
512	    // those rows describe the workload or the lattice. At least 3
513	    // decimals regardless of `--decimals`, since a fine quantum
514	    // renders as `0.0` at the report's default precision and zero
515	    // is the one value it must never claim.
516	    let quantum_str = fmt_commas_f64(
517	        quantum_ns(ticks::ticks_per_ns(), inner),
518	        cfg.decimals.max(3),
519	    );
520	
521	    // Column widths from rendered strings: band rows and the
522	    // summary lines that print in the mean column.
523	    let label_cols = rows
524	        .iter()
525	        .map(|r| display_cols(&r.label))
526	        .fold(display_cols(&stdev_trim_label), usize::max);
527	    let first_cols = rows
528	        .iter()
529	        .map(|r| display_cols(&r.first))
530	        .fold(0, usize::max);
531	    let last_cols = rows
532	        .iter()
533	        .map(|r| display_cols(&r.last))
534	        .fold(0, usize::max);
535	    let range_cols = rows
536	        .iter()
537	        .map(|r| display_cols(&r.range))
538	        .fold(0, usize::max);
539	    let count_cols = rows
540	        .iter()
541	        .map(|r| display_cols(&r.count))
542	        .fold(0, usize::max);
543	    // The mean column aligns on the decimal point rather than on
544	    // its last character, so each side is measured separately:
545	    // `quantum` prints at least three decimals while every other
546	    // row follows `--decimals`, and a shared right edge would
547	    // stagger the points (see [`decimal_align`]).
548	    let mean_values: Vec<&str> = rows
549	        .iter()
550	        .map(|r| r.mean.as_str())
551	        .chain([
552	            hist_mean_str.as_str(),
553	            hist_stdev_str.as_str(),
554	            quantum_str.as_str(),
555	        ])
556	        .chain(trim.iter().flat_map(|(m, s)| [m.as_str(), s.as_str()]))
557	        .chain(
558	            block_strs
559	                .iter()
560	                .flat_map(|(m, c, l)| [m.as_str(), c.as_str(), l.as_str()]),
561	        )
562	        .collect();
563	    let mean_int_cols = mean_values
564	        .iter()
565	        .map(|s| display_cols(split_decimal(s).0))
566	        .fold(0, usize::max);
567	    let mean_frac_cols = mean_values
568	        .iter()
569	        .map(|s| display_cols(split_decimal(s).1))
570	        .fold(0, usize::max);
571	    let mean_cols = mean_int_cols
572	        + if mean_frac_cols > 0 {
573	            mean_frac_cols + 1
574	        } else {
575	            0
576	        };
577	
578	    const INDENT: &str = "  ";
579	    const GAP: &str = "    ";
580	
581	    // Header row. Each label right-justifies to the last
582	    // character of its column's ` ns` unit; `count` is unitless
583	    // and right-justifies to its digits.
584	    const UNIT: usize = " ns".len();
585	    let first_col = INDENT.len() + label_cols + 1 + first_cols + UNIT;
586	    let last_gap = GAP.len() + last_cols + UNIT;
587	    let range_gap = GAP.len() + range_cols + UNIT;
588	    let count_gap = GAP.len() + count_cols;
589	    let mean_gap = GAP.len() + mean_cols + UNIT;
590	    println!(
591	        "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
592	        "first", "last", "range", "count", "mean",
593	    );
594	
595	    for r in &rows {
596	        println!(
597	            "{INDENT}{:<label_cols$} {:>first_cols$} ns{GAP}{:>last_cols$} ns{GAP}{:>range_cols$} ns{GAP}{:>count_cols$}{GAP}{} ns",
598	            r.label,
599	            r.first,
600	            r.last,
601	            r.range,
602	            r.count,
603	            decimal_align(&r.mean, mean_int_cols, mean_frac_cols),
604	        );
605	    }
606	
607	    // Whole-histogram summary. Aligned to the mean column.
608	    let skip = first_cols
609	        + " ns".len()
610	        + GAP.len()
611	        + last_cols
612	        + " ns".len()
613	        + GAP.len()
614	        + range_cols
615	        + " ns".len()
616	        + GAP.len()
617	        + count_cols;
618	    let cell = |s: &str| decimal_align(s, mean_int_cols, mean_frac_cols);
619	    println!(
620	        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
621	        "mean",
622	        "",
623	        cell(&hist_mean_str),
624	    );
625	    println!(
626	        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
627	        "stdev",
628	        "",
629	        cell(&hist_stdev_str),
630	    );
631	
632	    if let Some((trim_mean_str, trim_stdev_str)) = &trim {
633	        println!(
634	            "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
635	            mean_trim_label,
636	            "",
637	            cell(trim_mean_str),
638	        );
639	        println!(
640	            "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
641	            stdev_trim_label,
642	            "",
643	            cell(trim_stdev_str),
644	        );
645	    }
646	    println!(
647	        "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
648	        "quantum",
649	        "",
650	        cell(&quantum_str),
651	    );
652	    if let Some((block_mean_str, block_ci_str, block_lsc_str)) = &block_strs {
653	        println!(
654	            "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
655	            "mean blocks",
656	            "",
657	            cell(block_mean_str),
658	        );
659	        println!(
660	            "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
661	            "CI95",
662	            "",
663	            cell(block_ci_str),
664	        );
665	        println!(
666	            "{INDENT}{:<label_cols$} {:>skip$}{GAP}{} ns",
667	            "LSC",
668	            "",
669	            cell(block_lsc_str),
670	        );
671	    }
672	    // The grade block: one header over three rows, `env` grading
673	    // the *box* (two stretches: did warmup end settled, did the
674	    // bench stretch stay settled) above `run` grading *these*
675	    // numbers from the run's own batches. Each row's `worst` is
676	    // its own composite (worst signal wins), printed beside its
677	    // causes; a blank cell means the signal does not apply to
678	    // that row, which is the env/run signal mapping made
679	    // visible. Reported, never warned on — see [`crate::gauge`].
680	    let (warm, tail, during) = env_stretches(&out.probes, out.warmup_probes, out.warm_tail);
681	    let warm_grade = crate::gauge::EnvGrade::from_probes(tail);
682	    let bench_grade = crate::gauge::EnvGrade::from_probes(during);
683	    let run_grade = crate::gauge::RunGrade::from_batches(&out.batches);
684	    if warm_grade.is_some() || bench_grade.is_some() || run_grade.is_some() {
685	        println!();
686	        print_grade_line([
687	            "grade",
688	            "phase",
689	            "settle",
690	            "worst",
691	            "spread",
692	            "bursts",
693	            "interference",
694	            "drift",
695	            "step",
696	        ]);
697	    }
698	    // Settle time rides the warmup row because it describes that stretch alone: the
699	    // ramp the tail window now sits after. The cell answers by exit verdict: a settled
700	    // exit reports when and at what clock (RunOutput::warm_settle, scored in the
701	    // harness while the clock series was alive), a cap exit reports that it never did
702	    // ("not settled" is the exit condition's own finding), and an uncertified warm
703	    // says so instead of a time.
704	    let settled = match out.warm_exit {
705	        WarmExit::Uncertified => "uncertified".to_string(),
706	        WarmExit::Unstable => crate::gauge::Settle::Never.to_string(),
707	        WarmExit::Settled => match out.warm_settle {
708	            Some(s) => s.to_string(),
709	            None => GB_BLANK.to_string(),
710	        },
711	    };
712	    for (phase, grade, settle_cell) in [
713	        ("warmup", &warm_grade, settled.as_str()),
714	        ("bench", &bench_grade, GB_BLANK),
715	    ] {
716	        if let Some(g) = grade {
717	            let [sl_spread, sl_int, sl_drift, sl_step] = g.signal_letters();
718	            print_grade_line([
719	                "env",
720	                phase,
721	                settle_cell,
722	                &g.letter.to_string(),
723	                &pct_cell(g.spread_frac, sl_spread),
724	                GB_BLANK,
725	                &pct_cell(g.interference_frac, sl_int),
726	                &pct_cell(g.drift_frac, sl_drift),
727	                &step_cell(g.step_frac, g.step_at_s, sl_step),
728	            ]);
729	        }
730	    }
731	    if let Some(g) = run_grade {
732	        let [sl_int, sl_burst, sl_drift, sl_step] = g.signal_letters();
733	        print_grade_line([
734	            "run",
735	            "all",
736	            GB_BLANK,
737	            &g.letter.to_string(),
738	            GB_BLANK,
739	            &burst_cell(g.burst_frac, sl_burst),
740	            &pct_cell(g.interference_frac, sl_int),
741	            &pct_cell(g.drift_frac, sl_drift),
742	            &step_cell(g.step_frac, g.step_at_s, sl_step),
743	        ]);
744	    }
745	    // The complete warmup picture under -v: the per-probe table with the ramp's
746	    // shape, and where the exit window began.
747	    if log::log_enabled!(log::Level::Debug) && !warm.is_empty() {
748	        println!();
749	        let clock_cell = match out.warm_clock {
750	            Some(WarmClock {
751	                end_mhz,
752	                max_mhz: Some(max),
753	            }) => {
754	                format!(
755	                    ", clock {end_mhz:.0}/{max:.0} MHz ({:.1}%)",
756	                    end_mhz / max * 100.0
757	                )
758	            }
759	            Some(WarmClock {
760	                end_mhz,
761	                max_mhz: None,
762	            }) => format!(", clock {end_mhz:.0} MHz"),
763	            None => String::new(),
764	        };
765	        println!(
766	            "{INDENT}warmup probes ({} total, exit {:?}, window: last {} spanning \
767	             {:.1} ms{clock_cell}):",
768	            warm.len(),
769	            out.warm_exit,
770	            tail.len(),
771	            tail_span_ms(tail),
772	        );
773	        println!("{INDENT}      t ms   floor ns  spread ns   over %");
774	        for p in warm {
775	            let over_pct = if p.pairs == 0 {
776	                0.0
777	            } else {
778	                p.over_pairs as f64 / p.pairs as f64 * 100.0
779	            };
780	            println!(
781	                "{INDENT}{:>10.3} {:>10.3} {:>10.3} {:>8.2}",
782	                p.t_start_s * 1e3,
783	                p.floor_q_ps as f64 / PS_PER_NS,
784	                p.spread_q_ps as f64 / PS_PER_NS,
785	                over_pct,
786	            );
787	        }
788	    }
789	    warn_invalid(name, hist, suspended_s);
790	    println!();
791	}
792	
793	/// Wall span of a probe window (ms), first probe's start to the last's: the number the exit's
794	/// minimum-span rule constrains.
795	fn tail_span_ms(tail: &[ProbeSummary]) -> f64 {
796	    match (tail.first(), tail.last()) {
797	        (Some(first), Some(last)) => (last.t_start_s - first.t_start_s) * 1e3,
798	        _ => 0.0,
799	    }
800	}
801	
802	#[cfg(test)]
803	mod tests {
804	    use super::*;
805	
806	    /// A probe at `at` seconds with a flat floor; only the series length matters to the
807	    /// stretch split, so the quantiles are arbitrary.
808	    fn probe(at: f64, floor_ps: u64) -> ProbeSummary {
809	        ProbeSummary {
810	            t_start_s: at,
811	            groups: 128,
812	            floor_q_ps: floor_ps,
813	            spread_q_ps: floor_ps * 1008 / 1000,
814	            mean_ps: floor_ps as f64,
815	            pairs: 8192,
816	            over_pairs: 0,
817	        }
818	    }
819	
820	    #[test]
821	    fn decimal_align_lines_up_the_point() {
822	        // The case the `quantum` row created: three decimals beside a column of one.
823	        assert_eq!(decimal_align("24.0", 5, 3), "   24.0  ");
824	        assert_eq!(decimal_align("0.011", 5, 3), "    0.011");
825	    }
826	
827	    #[test]
828	    fn decimal_align_pads_a_fractionless_value_across_the_point() {
829	        // Reachable at `--decimals 0`, where `quantum` still prints three.
830	        assert_eq!(decimal_align("24", 5, 3), "   24    ");
831	    }
832	
833	    #[test]
834	    fn decimal_align_leaves_an_integer_column_alone() {
835	        assert_eq!(decimal_align("24", 5, 0), "   24");
836	    }
837	
838	    #[test]
839	    fn quantum_is_one_tick_over_inner() {
840	        // rpi5-20cd's 54 MHz Generic Timer: 18.5185 ns per tick, over the 23 calls a `min-now`
841	        // sample brackets, is the 0.805 ns lattice its band table shows.
842	        let q = quantum_ns(0.054, 23);
843	        assert!((q - 0.805).abs() < 0.001, "got {q}");
844	    }
845	
846	    #[test]
847	    fn quantum_shrinks_with_a_faster_clock() {
848	        // 3900X TSC at 3.792855 ticks/ns, same `inner`: ~70x finer, and invisible in a report.
849	        let q = quantum_ns(3.792855, 23);
850	        assert!((q - 0.0115).abs() < 0.0001, "got {q}");
851	    }
852	
853	    #[test]
854	    fn quantum_guards_degenerate_inputs() {
855	        assert_eq!(quantum_ns(0.0, 23), 0.0);
856	        assert_eq!(quantum_ns(3.792855, 0), 0.0);
857	    }
858	
859	    #[test]
860	    fn env_stretches_survives_a_short_series() {
861	        // `--no-env-probe` leaves only warmup probes, and fewer of them than the
862	        // recorded tail claims.
863	        let probes: Vec<ProbeSummary> = (0..3).map(|i| probe(i as f64 * 0.001, 24_000)).collect();
864	        let (warm, tail, during) = env_stretches(&probes, 16, 16);
865	        assert_eq!(warm.len(), 3);
866	        assert_eq!(tail.len(), 3);
867	        assert!(during.is_empty());
868	    }
869	
870	    /// A `band_count` vec (len = n_bands) with the given band
871	    /// indices marked populated.
872	    fn counts(n_bands: usize, populated: &[usize]) -> Vec<u64> {
873	        let mut c = vec![0u64; n_bands];
874	        for &i in populated {
875	            c[i] = 1;
876	        }
877	        c
878	    }
879	
880	    #[test]
881	    fn trim_range_label_spans_populated_bands() {
882	        let bounds = bands::boundaries();
883	        let n_bands = bounds.len() - 1;
884	        // OK: boundaries() always emits n2 (N_DEPTH >= 2)
885	        let trim_bands = bounds.iter().position(|b| b.zpn == "n2").unwrap();
886	
887	        // Full range: first band (label z4) through the n2 band.
888	        let c = counts(n_bands, &[0, 5, trim_bands - 1]);
889	        assert_eq!(
890	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
891	            "z4..n2"
892	        );
893	        assert_eq!(
894	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Both),
895	            "z4..n2"
896	        );
897	        assert_eq!(
898	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Frac),
899	            "0.000_1..0.99"
900	        );
901	
902	        // n2 band empty: upper end is the last populated band (p90).
903	        let c = counts(n_bands, &[0, 11]);
904	        assert_eq!(
905	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
906	            "z4..p90"
907	        );
908	
909	        // One populated band collapses to a single name.
910	        let c = counts(n_bands, &[8]);
911	        assert_eq!(
912	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
913	            "p60"
914	        );
915	
916	        // No populated trimmed band yields an empty label (unused).
917	        let c = counts(n_bands, &[]);
918	        assert_eq!(
919	            trim_range_label(&bounds, &c, trim_bands, BandLabels::Zpn),
920	            ""
921	        );
922	    }
923	
924	    #[test]
925	    fn band_index_right_closed_on_boundary() {
926	        let bounds = bands::boundaries();
927	        // Label of the band `mid_rank` falls in (bands labeled by
928	        // upper boundary → bounds[idx + 1]).
929	        let label = |r: f64| bounds[band_index(r, &bounds) + 1].zpn.as_str();
930	
931	        // Right-closed: a rank exactly on a boundary lands in the band
932	        // that boundary caps, not the next one up.
933	        assert_eq!(label(0.5), "p50"); // single-sample mid-rank
934	        assert_eq!(label(0.4), "p40"); // exactly the p40 boundary
935	        assert_eq!(label(0.99), "n2"); // exactly p99 → last non-tail band
936	        assert_eq!(label(0.01), "z2"); // exactly the z2 boundary
937	
938	        // Strictly-interior ranks are unaffected by the closed end.
939	        assert_eq!(label(0.45), "p50");
940	        assert_eq!(label(0.55), "p60");
941	        assert_eq!(label(0.05), "p10");
942	    }
